Install the SDK straight from its public GitHub repo; each platform page has the exact command. npm and pub.dev packages are coming soon. For React Native:

```bash
npm install github:bazingga08/strait-sdk-react-native#v0.8.0 @react-native-async-storage/async-storage react-native-play-install-referrer
```

Pick your platform: [React Native and Expo](https://straitlink.in/docs/sdks/react-native/) · [Flutter](https://straitlink.in/docs/sdks/flutter/) · [Android](https://straitlink.in/docs/sdks/android/) · [iOS](https://straitlink.in/docs/sdks/ios/) · [Unity](https://straitlink.in/docs/sdks/unity/) · [Web](https://straitlink.in/docs/sdks/web/). The shape is the same everywhere: create the client once with your publishable key and link domain, listen for links, start it.

```ts title="links.ts (React Native, @strait/sdk-react-native 0.8.0)"
import AsyncStorage from '@react-native-async-storage/async-storage';
import { PlayInstallReferrer } from 'react-native-play-install-referrer';
import { createStrait, fromPlayInstallReferrer } from '@strait/sdk-react-native';

export const links = createStrait({
  publishableKey: 'st_pub_live_…',        // Dashboard → Get started (safe in apps; never the secret key)
  endpoint: 'https://acme.strait.link',     // your Strait link host
  storage: AsyncStorage,            // required for reliable analytics
  installReferrer: fromPlayInstallReferrer(PlayInstallReferrer),
});

links.start();
```

Then send each link to a screen. With Expo Router:

```tsx title="app/_layout.tsx"
import { Stack, router, useRootNavigationState, type Href } from 'expo-router';
import { useEffect } from 'react';
import { links } from '../links';

export default function RootLayout() {
  const ready = useRootNavigationState()?.key;
  useEffect(() => {
    if (!ready) return;
    // Opened from a link, or first open after install: same callback.
    return links.onLink((e) => {
      if (e.matched && e.path) router.push({ pathname: e.path, params: e.params } as Href);
    });
  }, [ready]);
  return <Stack />;
}
```

Expo Router also needs a small `app/+native-intent.tsx`, and React Navigation apps use a navigation ref instead. Both are on the [React Native page](https://straitlink.in/docs/sdks/react-native/#route-links-to-screens).

:::warn Expo Go won't work
The setup uses a native module (`react-native-play-install-referrer`) and your app's own link settings, so you need a development build: `npx expo run:android` or `npx expo run:ios`, or a build from EAS Build. In Expo Go, links on your domain don't open your app.
:::

Create the client once, outside your components, and start it when the app launches.

```ts title="links.ts (@strait/sdk-react-native 0.8.0)"
import AsyncStorage from '@react-native-async-storage/async-storage';
import { PlayInstallReferrer } from 'react-native-play-install-referrer';
import { createStrait, fromPlayInstallReferrer } from '@strait/sdk-react-native';

export const links = createStrait({
  publishableKey: 'st_pub_live_…',        // Dashboard → Get started (safe in apps; never the secret key)
  endpoint: 'https://acme.strait.link',     // your Strait link host
  storage: AsyncStorage,            // required for reliable analytics
  installReferrer: fromPlayInstallReferrer(PlayInstallReferrer),
});

links.start();
```

`endpoint` is your workspace's link domain. The SDK sends its requests there, and treats links on that host as yours: it looks them up and reports the open. There's also an optional `linkHosts` list for extra hosts that serve your links; with one link domain per workspace you don't need it.

Call `start()` once. `onLink` replays past events to late subscribers, so you won't miss the launch link if your navigator mounts after `start()`.

`e.path` is the destination's path (`/product/42`) and `e.params` its query parameters. Send them to a screen once your navigator is ready.

### Expo Router

```tsx title="app/_layout.tsx"
import { Stack, router, useRootNavigationState, type Href } from 'expo-router';
import { useEffect } from 'react';
import { links } from '../links';

export default function RootLayout() {
  const ready = useRootNavigationState()?.key;
  useEffect(() => {
    if (!ready) return;
    // Opened from a link, or first open after install: same callback.
    return links.onLink((e) => {
      if (e.matched && e.path) router.push({ pathname: e.path, params: e.params } as Href);
    });
  }, [ready]);
  return <Stack />;
}
```

Expo Router also tries to open every incoming link itself, and `https://acme.strait.link/summer` isn't a screen in your app. Add this file so it opens your first screen instead and lets `onLink` do the routing:

```tsx title="app/+native-intent.tsx"
// Links reach the app through Strait's onLink (app/_layout.tsx), which knows the
// real destination. Keep Expo Router from routing the raw link URL.
export function redirectSystemPath({ path }: { path: string; initial: boolean }) {
  return '/';
}
```

If your app has other deep links of its own (for example a sign-in callback), return `path` for those instead of `'/'`.

### React Navigation

```tsx title="navigation.ts"
import { createNavigationContainerRef } from '@react-navigation/native';

export const navigationRef = createNavigationContainerRef<any>();

// Map a link's path to one of your screens.
export function openPath(path: string, params: Record<string, string> = {}) {
  const product = /^\/product\/([^/]+)$/.exec(path);
  if (product) navigationRef.navigate('Product', { id: product[1], ...params });
  else navigationRef.navigate('Home');
}
```

```tsx title="App.tsx"
import { NavigationContainer } from '@react-navigation/native';
import { links } from './links';
import { navigationRef, openPath } from './navigation';

export default function App() {
  return (
    <NavigationContainer
      ref={navigationRef}
      onReady={() => links.onLink((e) => e.matched && e.path && openPath(e.path, e.params))}
    >
      {/* your navigator */}
    </NavigationContainer>
  );
}
```

Don't also list your link domain in React Navigation's `linking` option, or each link is handled twice.

### Show a loading state (optional)

A link can take a second or more to resolve on a slow network. `onLinkStart` fires as soon as it arrives:

```tsx title="LinkLoading.tsx"
import { useEffect, useState } from 'react';
import { ActivityIndicator, StyleSheet } from 'react-native';
import { links } from './links';

export function LinkLoading() {
  const [opening, setOpening] = useState(false);
  useEffect(() => {
    const offStart = links.onLinkStart(() => setOpening(true));
    const offLink = links.onLink(() => setOpening(false));
    return () => { offStart(); offLink(); };
  }, []);
  return opening ? <ActivityIndicator style={StyleSheet.absoluteFill} size="large" /> : null;
}
```

If you only want the first-open-after-install destination, there's a one-call API. It never throws; on any error it returns `{ matched: false, matchMethod: 'none' }`.

```ts
import { resolveDeferredLink, splitUrl } from '@strait/sdk-react-native';
import { navigationRef, openPath } from './navigation';

const result = await resolveDeferredLink({
  publishableKey: 'st_pub_live_…',
  endpoint: 'https://acme.strait.link',
});
const dest = result.matched && result.longUrl ? splitUrl(result.longUrl) : null;
if (dest && navigationRef.isReady()) openPath(dest.path, dest.params);
```

```dart title="links.dart"
import 'dart:async';
import 'dart:io' show Platform;
import 'dart:ui';

import 'package:app_links/app_links.dart';
import 'package:strait_sdk/strait_sdk.dart';
import 'package:flutter/widgets.dart';
import 'package:flutter_timezone/flutter_timezone.dart';
import 'package:play_install_referrer/play_install_referrer.dart';
import 'package:shared_preferences/shared_preferences.dart';

/// Persists the once-per-install flag and unsent open reports.
class PrefsStore implements KeyValueStore {
  PrefsStore(this.prefs);
  final SharedPreferences prefs;
  @override
  Future<String?> get(String key) async => prefs.getString(key);
  @override
  Future<void> set(String key, String value) => prefs.setString(key, value);
}

/// Feeds Flutter lifecycle changes to the SDK.
class LifecycleFeed with WidgetsBindingObserver {
  final _ctl = StreamController<AppLifecycle>.broadcast(sync: true);
  Stream<AppLifecycle> get stream => _ctl.stream;
  LifecycleFeed() { WidgetsBinding.instance.addObserver(this); }
  @override
  void didChangeAppLifecycleState(AppLifecycleState s) => _ctl.add(switch (s) {
        AppLifecycleState.resumed => AppLifecycle.active,
        AppLifecycleState.inactive => AppLifecycle.inactive,
        _ => AppLifecycle.background,
      });
}

Future<StraitLinks> startLinks() async {
  WidgetsFlutterBinding.ensureInitialized();
  final timezone = await FlutterTimezone.getLocalTimezone(); // IANA, e.g. Asia/Kolkata
  final links = StraitLinks(
    publishableKey: 'st_pub_live_…',      // Dashboard → Get started
    endpoint: 'https://acme.strait.link',   // your workspace's link domain
    platform: Platform.isIOS ? 'ios' : Platform.isAndroid ? 'android' : 'other',
    storage: PrefsStore(await SharedPreferences.getInstance()),
    installReferrer: () async =>
        Platform.isAndroid ? (await PlayInstallReferrer.installReferrer).installReferrer : null,
    deviceFields: () {
      final view = PlatformDispatcher.instance.views.first;
      return DeviceFields(
        screenWidth: portraitScreenWidth(view.physicalSize.width / view.devicePixelRatio, view.physicalSize.height / view.devicePixelRatio),
        pixelRatio: view.devicePixelRatio,
        language: PlatformDispatcher.instance.locale.toLanguageTag(),
        timezone: timezone,
      );
    },
  );

  // Subscribe before start() (past events replay anyway).
  links.onLinkStart.listen((s) { /* show "Opening link…" */ });
  links.onLink.listen((e) {
    if (e.matched && e.path != null) {
      // navigate to e.path with e.params
    }
  });

  final appLinks = AppLinks();
  await links.start(
    initialUrl: (await appLinks.getInitialLink())?.toString(),
    urls: appLinks.uriLinkStream.map((u) => u.toString()),
    lifecycle: LifecycleFeed().stream,
  );
  return links;
}
```

:::tip Two things that trip people up
- **Time zone**: pass the IANA name (`Asia/Kolkata`). `DateTime.timeZoneName` is an abbreviation on some platforms and won't match. With `flutter_timezone` 4.x use `.identifier`.
- **Launch link twice**: `app_links` 6+ also emits the launch link on `uriLinkStream`. `start()` ignores that first echo, so the launch link is handled once.
:::

```kotlin title="App.kt"
import android.app.Application
import androidx.lifecycle.Lifecycle
import androidx.lifecycle.LifecycleEventObserver
import androidx.lifecycle.ProcessLifecycleOwner
import dev.strait.sdk.AppLifecycleState
import dev.strait.sdk.DeviceFields
import dev.strait.sdk.KeyValueStore
import dev.strait.sdk.StraitClient
import dev.strait.sdk.StraitConfig
import dev.strait.sdk.portraitScreenWidth

class App : Application() {
    lateinit var links: StraitClient

    override fun onCreate() {
        super.onCreate()
        val prefs = getSharedPreferences("links", MODE_PRIVATE)
        links = StraitClient(StraitConfig(
            publishableKey = "st_pub_live_…",          // Dashboard → Get started
            endpoint = "https://acme.strait.link",       // your workspace's link domain
            storage = object : KeyValueStore {
                override fun get(key: String) = prefs.getString(key, null)
                override fun set(key: String, value: String) { prefs.edit().putString(key, value).apply() }
            },
            installReferrer = { readInstallReferrer(this) },
            device = {
                val m = resources.displayMetrics
                DeviceFields(
                    screenWidth = portraitScreenWidth(m.widthPixels / m.density.toDouble(), m.heightPixels / m.density.toDouble()),
                    pixelRatio = m.density.toDouble(),
                    language = java.util.Locale.getDefault().toLanguageTag(),
                    timezone = java.util.TimeZone.getDefault().id,
                )
            },
            executor = java.util.concurrent.Executors.newSingleThreadExecutor(),
        ))

        // App state: background vs foreground labels, and retrying saved reports.
        ProcessLifecycleOwner.get().lifecycle.addObserver(LifecycleEventObserver { _, e ->
            when (e) {
                Lifecycle.Event.ON_RESUME -> links.onAppState(AppLifecycleState.ACTIVE)
                Lifecycle.Event.ON_PAUSE -> links.onAppState(AppLifecycleState.INACTIVE)
                Lifecycle.Event.ON_STOP -> links.onAppState(AppLifecycleState.BACKGROUND)
                else -> Unit
            }
        })
    }
}
```

```kotlin title="MainActivity.kt"
import android.content.Intent
import android.os.Bundle
import androidx.appcompat.app.AppCompatActivity

class MainActivity : AppCompatActivity() {
    private val links get() = (application as App).links

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        links.onLinkStart { runOnUiThread { showOpeningLink() } }
        links.onLink { e -> runOnUiThread { if (e.matched) navigate(e.path, e.params) else hideOpeningLink() } }
        // Launched from closed: the intent's URL (or null). Runs the deferred check once per install.
        if (savedInstanceState == null) links.start(intent?.dataString)
    }

    override fun onNewIntent(intent: Intent) {
        super.onNewIntent(intent)
        intent.dataString?.let(links::handleUrl)   // app was already running
    }

    // Replace these three with your own loading UI and navigation.
    private fun showOpeningLink() { /* show a spinner */ }
    private fun hideOpeningLink() { /* hide it */ }
    private fun navigate(path: String?, params: Map<String, String>?) {
        hideOpeningLink()
        val id = path?.removePrefix("/product/")?.takeIf { it != path } ?: return
        startActivity(Intent(this, ProductActivity::class.java).putExtra("id", id))
    }
}
```

Your manifest needs the App Links intent filter for `acme.strait.link` and your custom scheme; see [Quick start, step 5](https://straitlink.in/docs/quick-start/#5-let-the-phone-open-your-app).

```kotlin title="InstallReferrer.kt"
import android.content.Context
import com.android.installreferrer.api.InstallReferrerClient
import com.android.installreferrer.api.InstallReferrerStateListener

fun readInstallReferrer(context: Context): String? {
    val latch = java.util.concurrent.CountDownLatch(1)
    var result: String? = null
    val client = InstallReferrerClient.newBuilder(context).build()
    try {
        client.startConnection(object : InstallReferrerStateListener {
            override fun onInstallReferrerSetupFinished(code: Int) {
                if (code == InstallReferrerClient.InstallReferrerResponse.OK) {
                    result = runCatching { client.installReferrer.installReferrer }.getOrNull()
                }
                latch.countDown()
            }
            override fun onInstallReferrerServiceDisconnected() { latch.countDown() }
        })
        latch.await(5, java.util.concurrent.TimeUnit.SECONDS)
    } catch (_: Exception) {
    } finally {
        runCatching { client.endConnection() }
    }
    return result
}
```

When someone without your app taps a link, we send them to Google Play with the link in the install referrer. On first open the SDK reads it and resolves the exact link and tap. No guessing.

Create one client at launch and keep it for the app's lifetime.

```swift
import StraitSDK

let links = StraitLinks(StraitLinksConfig(
    publishableKey: "st_pub_live_…",          // Dashboard → Get started
    endpoint: "https://acme.strait.link"        // your workspace's link domain
))

links.onLinkStart { start in showOpeningLink(start.id) }   // loading state
links.onLink { event in                                    // replays past events
    guard event.matched, let path = event.path else { return }
    router.open(path, params: event.params ?? [:])
}
```

```swift title="SceneDelegate.swift"
func scene(_ scene: UIScene, willConnectTo session: UISceneSession, options: UIScene.ConnectionOptions) {
    // The link that launched the app from closed (Universal Link or custom scheme).
    let launchURL = options.userActivities.first(where: { $0.activityType == NSUserActivityTypeBrowsingWeb })?.webpageURL
        ?? options.urlContexts.first?.url
    links.start(initialURL: launchURL)       // also runs the deferred check, once per install
}

func scene(_ scene: UIScene, continue userActivity: NSUserActivity) {
    links.handle(userActivity: userActivity)  // Universal Link while running
}

func scene(_ scene: UIScene, openURLContexts URLContexts: Set<UIOpenURLContext>) {
    URLContexts.forEach { links.handle(url: $0.url) }   // yourapp://… browser hand-off
}
```

Without scenes, do the same from `application(_:didFinishLaunchingWithOptions:)`, `application(_:continue:restorationHandler:)` and `application(_:open:options:)`.

```swift
@main struct ShopApp: App {
    init() { links.start() }
    var body: some Scene {
        WindowGroup {
            ContentView()
                .onOpenURL { links.handle(url: $0) }
                .onContinueUserActivity(NSUserActivityTypeBrowsingWeb) { links.handle(userActivity: $0) }
        }
